// device row-level security and registry integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); site/client consistency and R6 backstop cases added (E4 AC1).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  device,
  eq,
  inActorTransaction,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'L' as const,
});
const deviceOf = (
  clientId: string,
  siteId: string,
  sn: string,
  more: Partial<typeof device.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  sn,
  model: 'G6',
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(device)).map((r) => r.sn).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx
      .insert(device)
      .values([
        deviceOf(clientA, siteA, 'SN-A1', { visibility: 'client', mac: 'AA:BB:CC:00:00:01' }),
        deviceOf(clientA, siteA, 'SN-A2'),
        deviceOf(clientB, siteB, 'SN-B1'),
      ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every device', async () => {
  expect(await visibleTo(staff)).toEqual(['SN-A1', 'SN-A2', 'SN-B1']);
});

it('a client sees only its own devices marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['SN-A1']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(device).values(deviceOf(clientA, siteA, 'SN-X')),
    ),
  ).rejects.toThrow();
});

it("a device's client is always its site's client", async () => {
  await expect(asStaff((tx) => tx.insert(device).values(deviceOf(clientA, siteB, 'SN-X')))).rejects.toThrow();
});

it('R6 backstop: the same SN (any case) is refused among active devices', async () => {
  await expect(
    asStaff((tx) => tx.insert(device).values(deviceOf(clientB, siteB, 'sn-a1'))),
  ).rejects.toThrow();
});

it('D-29: the MAC is not an identity — two active devices may report the same MAC', async () => {
  await asStaff((tx) =>
    tx.insert(device).values(deviceOf(clientB, siteB, 'SN-B2', { mac: 'AA:BB:CC:00:00:01' })),
  );
  expect(await visibleTo(staff)).toContain('SN-B2');
});

it('an archived device frees its SN', async () => {
  await asStaff((tx) => tx.update(device).set({ archivedAt: new Date() }).where(eq(device.sn, 'SN-A1')));
  await asStaff((tx) =>
    tx.insert(device).values(deviceOf(clientA, siteA, 'SN-A1', { mac: 'AA:BB:CC:00:00:01' })),
  );
  expect((await visibleTo(staff)).filter((sn) => sn === 'SN-A1')).toHaveLength(2);
});

it('MAC is stored in one spelling and status is from the life cycle', async () => {
  await expect(
    asStaff((tx) =>
      tx.insert(device).values(deviceOf(clientB, siteB, 'SN-B3', { mac: 'aa-bb-cc-00-00-03' })),
    ),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) =>
      tx.insert(device).values({ ...deviceOf(clientB, siteB, 'SN-B4'), status: 'broken' as 'faulty' }),
    ),
  ).rejects.toThrow();
});
